def format_bytes(n):
    if n == 0:
        return '0 B'
    result = ''
    divisors = [1024, 1024**2, 1024**3, 1024**4, 1024**5, 1024**6, 1024**7, 1024**8]
    units = ['KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB']
    for divisor, unit in zip(divisors, units):
        if n >= divisor:
            n = n / divisor
            result = f'{n:.2f} {unit}'
    return result
